CREATE OR REPLACE FUNCTION public.create_technical_visit_secure(
  p_cliente_id uuid,
  p_fazenda_id uuid,
  p_talhao_id uuid DEFAULT NULL,
  p_solicitacao_origem_id uuid DEFAULT NULL,
  p_scheduled_at timestamptz DEFAULT NULL,
  p_visit_type public.tipo_visita DEFAULT 'vistoria_inicial',
  p_priority public.urgencia_consultor DEFAULT 'media',
  p_initial_notes text DEFAULT NULL,
  p_client_uuid uuid DEFAULT NULL
)
RETURNS TABLE(registro_id uuid, is_new boolean)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_existing uuid;
  v_vinculo record;
  v_new_id uuid;
BEGIN
  -- 1) Auth
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  -- 2) Idempotência por client_uuid
  IF p_client_uuid IS NOT NULL THEN
    SELECT id INTO v_existing
      FROM public.registros_consultor
     WHERE client_uuid = p_client_uuid
     LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN QUERY SELECT v_existing, false;
      RETURN;
    END IF;
  END IF;

  -- 3) Admin bypass
  SELECT public.has_role(v_uid, 'administrador'::app_role) INTO v_is_admin;

  -- 4) Vínculo técnico
  IF NOT v_is_admin THEN
    SELECT * INTO v_vinculo
      FROM public.user_clientes
     WHERE user_id = v_uid
       AND cliente_id = p_cliente_id
       AND is_active = true
       AND (valid_from IS NULL OR valid_from <= now())
       AND (valid_until IS NULL OR valid_until >= now())
       AND access_level IN ('execute','manage')
     LIMIT 1;

    IF v_vinculo.id IS NULL THEN
      RAISE EXCEPTION 'no_active_binding_or_insufficient_access' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 5) Cliente ativo
  IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = p_cliente_id) THEN
    RAISE EXCEPTION 'cliente_not_found' USING ERRCODE = '22023';
  END IF;

  -- 6) Fazenda pertence ao cliente
  IF NOT EXISTS (
    SELECT 1 FROM public.fazendas
     WHERE id = p_fazenda_id AND cliente_id = p_cliente_id
  ) THEN
    RAISE EXCEPTION 'fazenda_does_not_belong_to_cliente' USING ERRCODE = '22023';
  END IF;

  -- 7) Talhão pertence à fazenda
  IF p_talhao_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.talhoes
       WHERE id = p_talhao_id AND fazenda_id = p_fazenda_id
    ) THEN
      RAISE EXCEPTION 'talhao_does_not_belong_to_fazenda' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 8) Solicitação pertence ao mesmo cliente
  IF p_solicitacao_origem_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.portal_solicitacoes
       WHERE id = p_solicitacao_origem_id AND cliente_id = p_cliente_id
    ) THEN
      RAISE EXCEPTION 'solicitacao_mismatch_cliente' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 9) Insert
  INSERT INTO public.registros_consultor(
    cliente_id, fazenda_id, talhao_id,
    consultor_responsavel, created_by,
    solicitacao_id, tipo_visita, urgencia,
    natureza_registro, status,
    observacoes_tecnicas, data_vistoria,
    client_uuid
  ) VALUES (
    p_cliente_id, p_fazenda_id, p_talhao_id,
    v_uid, v_uid,
    p_solicitacao_origem_id, p_visit_type, p_priority,
    'visita', 'rascunho',
    p_initial_notes, COALESCE(p_scheduled_at::date, CURRENT_DATE),
    p_client_uuid
  )
  RETURNING id INTO v_new_id;

  -- 10) Log de auditoria
  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (
    v_new_id, p_solicitacao_origem_id, 'visita_criada',
    'Visita técnica criada via create_technical_visit_secure',
    v_uid,
    jsonb_build_object(
      'tipo_visita', p_visit_type,
      'urgencia', p_priority,
      'admin_bypass', v_is_admin
    )
  );

  RETURN QUERY SELECT v_new_id, true;
END;
$$;

REVOKE ALL ON FUNCTION public.create_technical_visit_secure(uuid,uuid,uuid,uuid,timestamptz,public.tipo_visita,public.urgencia_consultor,text,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_technical_visit_secure(uuid,uuid,uuid,uuid,timestamptz,public.tipo_visita,public.urgencia_consultor,text,uuid) TO authenticated, service_role;

-- Novo status "em_andamento" (visita com check-in feito)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_enum e
    JOIN pg_type t ON t.oid = e.enumtypid
    WHERE t.typname = 'status_registro_consultor' AND e.enumlabel = 'em_andamento'
  ) THEN
    ALTER TYPE public.status_registro_consultor ADD VALUE 'em_andamento' BEFORE 'finalizado';
  END IF;
END$$;

-- =========================================================
-- start_technical_visit_secure
-- =========================================================
CREATE OR REPLACE FUNCTION public.start_technical_visit_secure(
  p_registro_id uuid,
  p_latitude numeric DEFAULT NULL,
  p_longitude numeric DEFAULT NULL,
  p_precisao_gps numeric DEFAULT NULL,
  p_foto_url text DEFAULT NULL,
  p_foto_path text DEFAULT NULL,
  p_observacoes text DEFAULT NULL,
  p_justificativa_sem_gps text DEFAULT NULL,
  p_client_uuid uuid DEFAULT NULL
)
RETURNS TABLE(checkin_id uuid, is_new boolean)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_reg record;
  v_existing uuid;
  v_new_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  -- Idempotência por client_uuid
  IF p_client_uuid IS NOT NULL THEN
    SELECT id INTO v_existing FROM public.visitas_checkin WHERE client_uuid = p_client_uuid LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN QUERY SELECT v_existing, false;
      RETURN;
    END IF;
  END IF;

  SELECT * INTO v_reg FROM public.registros_consultor WHERE id = p_registro_id;
  IF v_reg.id IS NULL THEN
    RAISE EXCEPTION 'registro_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT public.has_role(v_uid, 'administrador'::app_role) INTO v_is_admin;

  -- Só técnico da visita ou admin
  IF NOT v_is_admin AND v_reg.consultor_responsavel IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- Status permitido
  IF v_reg.status NOT IN ('rascunho') THEN
    RAISE EXCEPTION 'invalid_status_for_start:%', v_reg.status USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.visitas_checkin(
    registro_consultor_id, solicitacao_id, consultor_id,
    cliente_id, fazenda_id, talhao_id,
    latitude, longitude, precisao_gps,
    foto_url, foto_path, observacoes,
    justificativa_sem_gps, tipo_checkin, status, client_uuid
  ) VALUES (
    v_reg.id, v_reg.solicitacao_id, v_uid,
    v_reg.cliente_id, v_reg.fazenda_id, v_reg.talhao_id,
    p_latitude, p_longitude, p_precisao_gps,
    p_foto_url, p_foto_path, p_observacoes,
    p_justificativa_sem_gps, 'chegada_fazenda', 'realizado', p_client_uuid
  )
  RETURNING id INTO v_new_id;

  UPDATE public.registros_consultor
     SET status = 'em_andamento',
         hora_inicio = COALESCE(hora_inicio, now()),
         updated_at = now()
   WHERE id = v_reg.id;

  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (v_reg.id, v_reg.solicitacao_id, 'checkin', 'Check-in de visita técnica', v_uid,
          jsonb_build_object('checkin_id', v_new_id, 'admin_bypass', v_is_admin));

  RETURN QUERY SELECT v_new_id, true;
END;
$$;

